// ── Reduced motion CSS (WCAG 2.3.3) — shared across all STEAM Lab tools ──
(function() {
  if (typeof document === 'undefined') return;
  if (document.getElementById('allo-stem-motion-reduce-css')) return;
  var st = document.createElement('style');
  st.id = 'allo-stem-motion-reduce-css';
  st.textContent = '@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; } }';
  if (document.head) document.head.appendChild(st);
})();

// Where this tool was loaded from — captured at parse time (document.currentScript
// is null by the time the 3-D canvas mounts). In Gemini Canvas document.baseURI is
// a blob: URL, which is an INVALID base for new URL() and throws — so every
// local-asset path resolves against the script's own origin first, and a failed
// resolution yields '' (callers filter it out and fall through to public CDNs).
var __alloBrainAtlasScriptUrl = (function () {
  if (typeof document === 'undefined') return '';
  var current = document.currentScript;
  return current && current.src ? current.src : '';
})();
function __alloBrainAtlasAssetUrl(fromScript, fromBase) {
  try {
    if (__alloBrainAtlasScriptUrl) return new URL(fromScript, __alloBrainAtlasScriptUrl).href;
    return new URL(fromBase, document.baseURI).href;
  } catch (_) { return ''; }
}

// Theme-aware ink for accent colours used both as fills (keep the hue) and
// as small text (needs a readable member of the same hue family per theme).
var BA_INK_DARK = { '#7c3aed': '#c4b5fd', '#0f766e': '#5eead4', '#2563eb': '#93c5fd', '#dc2626': '#fca5a5', '#ef4444': '#fca5a5', '#16a34a': '#86efac', '#d97706': '#fcd34d', '#0ea5e9': '#7dd3fc', '#e11d48': '#fda4af' };
var BA_INK_LIGHT = { '#dc2626': '#b91c1c', '#ef4444': '#b91c1c', '#16a34a': '#166534', '#0ea5e9': '#0369a1', '#7c3aed': '#6d28d9' };
function __alloBrainAtlasInk(color) {
  var dk = typeof document !== 'undefined' && document.querySelector('.theme-dark,.theme-contrast,[data-stem-theme=dark],[data-stem-theme=contrast]');
  return (dk ? BA_INK_DARK[color] : BA_INK_LIGHT[color]) || color;
}

// Match the anatomical plate's lobe tints in the connected region guide.
function __alloBrainAtlasRegionAccent(region, view) {
  if (view !== 'lateral' && view !== 'superior') return '#8b5cf6';
  var id = region && region.id || '';
  if (/^(frontal|prefrontal|motor|brocas?)(_|$)/.test(id)) return '#3b82f6';
  if (/^(parietal|somatosensory|supramarginal|angular)(_|$)/.test(id)) return '#22c55e';
  if (/^(temporal|auditory|wernickes?)(_|$)/.test(id)) return '#eab308';
  if (/^(occipital|visual)(_|$)/.test(id)) return '#ef4444';
  return '#8b5cf6';
}

// Standard labels prioritize landmarks, rather than whichever entries happen
// to occur at a particular interval in the region directory.
var BA_ANATOMY_LANDMARKS = {
  lateral: ['frontal','parietal','temporal','occipital','cerebellum','brainstem'],
  medial: ['corpus_callosum','thalamus','hypothalamus','cingulate','hippocampus','ventricles'],
  superior: ['longitudinal','central_sulcus','frontal_sup','parietal_sup','sma'],
  inferior: ['olfactory','optic_chiasm','temporal_inf','cerebellum_inf','medulla_inf','circle_willis_brain']
};
var BA_ANATOMY_ORIENTATION = {
  lateral: {label:'Side view', horizontal:'Front at left \u00b7 Back at right', vertical:'Top above \u00b7 Base below'},
  medial: {label:'Inner midline view', horizontal:'Front at left \u00b7 Back at right', vertical:'Top above \u00b7 Base below'},
  superior: {label:'View from above', horizontal:'Both hemispheres', vertical:'Front at top \u00b7 Back at bottom'},
  inferior: {label:'View from below', horizontal:'Base of the brain', vertical:'Front at top \u00b7 Back at bottom'}
};

// One teaching clock drives the curve, phase labels and decoder. The peak is
// held briefly for inspection; the horizontal axis intentionally has no time units.
var BA_SPIKE_SAMPLES = [[0,-70],[.14,-70],[.24,-67],[.34,-55],[.42,18],[.48,30],[.55,-22],[.63,-70],[.66,-80],[.80,-73],[1,-70]];
var BA_SPIKE_PHASES = [
  {label:'Resting', short:'Rest', detail:'The membrane starts near \u221270 mV.', color:'#1d4ed8', cardIndex:-1},
  {label:'Stimulus', short:'Stimulus', detail:'The voltage rises toward the \u221255 mV threshold.', color:'#b91c1c', cardIndex:-1},
  {label:'Depolarization', short:'Depolarize', detail:'Sodium enters and the voltage rises rapidly.', color:'#6d28d9', cardIndex:0},
  {label:'Peak', short:'Peak', detail:'The voltage reaches about +30 mV before falling.', color:'#6d28d9', cardIndex:-1},
  {label:'Repolarization', short:'Repolarize', detail:'Potassium exits and the voltage falls toward rest.', color:'#166534', cardIndex:1},
  {label:'Recovery', short:'Recover', detail:'The voltage dips below rest, then returns toward \u221270 mV.', color:'#92400e', cardIndex:2}
];
function __alloBrainAtlasSpikeState(position) {
  var cycle = Number.isFinite(Number(position)) ? Math.max(0, Number(position)) % 6 : 0;
  var phaseIndex = Math.floor(cycle), fraction = cycle - phaseIndex;
  var anchors = [0,.14,.34,.48,.48,.63,1];
  var x = anchors[phaseIndex] + (anchors[phaseIndex + 1] - anchors[phaseIndex]) * fraction;
  var segment = 0;
  while (segment < BA_SPIKE_SAMPLES.length - 2 && x > BA_SPIKE_SAMPLES[segment + 1][0]) segment++;
  var a = BA_SPIKE_SAMPLES[segment], b = BA_SPIKE_SAMPLES[segment + 1];
  var voltage = a[1] + (b[1] - a[1]) * (x - a[0]) / (b[0] - a[0]);
  var info = BA_SPIKE_PHASES[phaseIndex];
  return {phaseIndex:phaseIndex, label:info.label, x:x, voltage:voltage, color:info.color, cardIndex:info.cardIndex};
}
function __alloBrainAtlasVoltageLabel(voltage) {
  var rounded = Math.round(voltage);
  return (rounded < 0 ? '\u2212' : rounded > 0 ? '+' : '') + Math.abs(rounded) + ' mV';
}

