    '.brainatlas-psych-compare-count{display:inline-flex;align-items:center;min-height:32px;border:1px solid var(--ba-border);border-radius:999px;background:var(--ba-surface);color:var(--ba-muted);padding:5px 8px;font-size:12px;font-weight:950;white-space:nowrap;}',
    '.brainatlas-psych-compare-clear{min-height:36px;border:1px solid var(--ba-button-border);border-radius:8px;background:var(--ba-button);color:var(--ba-button-text);padding:5px 8px;font-size:12px;font-weight:950;}',
