    '.brainatlas-canvas-summary strong{display:block;color:var(--ba-text);font-size:13px;margin-bottom:5px;font-weight:700;}',
    '.brainatlas-teacher-prompt{min-width:0;border-left:1px solid var(--ba-border);background:var(--ba-panel);color:var(--ba-muted);padding:16px 18px;font-size:14px;line-height:1.55;overflow-wrap:anywhere;}',
