    '.brainatlas-region-item{position:relative;display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:start;gap:12px;min-height:102px;padding:16px!important;border:1px solid var(--ba-border)!important;border-radius:13px!important;background:var(--ba-surface)!important;scroll-margin-block:6px;overflow:visible;overflow-wrap:anywhere;transition:border-color .18s ease,box-shadow .18s ease,transform .18s ease;}',
